{
  "workflow": {
    "activities": [
      {
        "id": "A1",
        "name": "Collect Meeting Source Materials",
        "actor": "Minute Taker",
        "system": "Calendar System",
        "inputs": ["Meeting agenda", "Meeting notes or transcript", "Action items list captured during meeting"],
        "outputs": ["Compiled source material package"]
      },
      {
        "id": "A2",
        "name": "Check for Confidential Content",
        "actor": "Minute Taker",
        "system": "None (manual review)",
        "inputs": ["Compiled source material package"],
        "outputs": ["Confidentiality flag"]
      },
      {
        "id": "A3",
        "name": "Extract Decisions and Action Items",
        "actor": "Minute Taker",
        "system": "None (manual)",
        "inputs": ["Compiled source material package"],
        "outputs": ["List of decisions made", "List of action items with owners and deadlines"]
      },
      {
        "id": "A4",
        "name": "Clarify Unclear Items",
        "actor": "Minute Taker",
        "system": "Email Client or direct communication",
        "inputs": ["Ambiguous notes or action items"],
        "outputs": ["Confirmed decisions and action items"]
      },
      {
        "id": "A5",
        "name": "Draft Meeting Summary",
        "actor": "Minute Taker",
        "system": "None (manual document creation)",
        "inputs": ["List of decisions made", "Confirmed action items with owners and deadlines", "Supporting materials or attachments"],
        "outputs": ["Draft meeting summary document"]
      },
      {
        "id": "A6",
        "name": "Determine Email Recipients",
        "actor": "Minute Taker",
        "system": "Calendar System",
        "inputs": ["Attendee list from calendar", "Meeting content and decisions"],
        "outputs": ["Curated email distribution list"]
      },
      {
        "id": "A7",
        "name": "Send Meeting Summary Email",
        "actor": "Minute Taker",
        "system": "Email Client",
        "inputs": ["Draft meeting summary document", "Curated email distribution list", "Supporting materials or links"],
        "outputs": ["Sent summary email"]
      },
      {
        "id": "A8",
        "name": "Log Action Items in Task Tracker",
        "actor": "Minute Taker",
        "system": "Task Tracker",
        "inputs": ["Confirmed action items with owners and deadlines"],
        "outputs": ["Task tracker entries for each action item"]
      },
      {
        "id": "A9",
        "name": "Escalate Confidential Meeting Notes",
        "actor": "Minute Taker",
        "system": "None (manual escalation)",
        "inputs": ["Confidential source material", "Confidentiality flag"],
        "outputs": ["Escalation notification to appropriate authority"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Does the meeting source material contain confidential or sensitive content?",
        "branches": [
          "Yes → Route to A9 (Escalate Confidential Meeting Notes); halt standard distribution",
          "No → Proceed to A3 (Extract Decisions and Action Items)"
        ]
      },
      {
        "id": "D2",
        "condition": "Are there any unclear or ambiguous items in the notes?",
        "branches": [
          "Yes → Route to A4 (Clarify Unclear Items) before proceeding to A5",
          "No → Proceed directly to A5 (Draft Meeting Summary)"
        ]
      },
      {
        "id": "D3",
        "condition": "Are there action items that need to be logged in the task tracker?",
        "branches": [
          "Yes → Proceed to A8 (Log Action Items in Task Tracker) after A7",
          "No → Process ends after A7"
        ]
      }
    ],
    "exceptions": [
      {
        "id": "E1",
        "description": "Meeting notes contain confidential or sensitive content",
        "trigger": "Minute taker identifies confidential material during review",
        "current_handling": "No formal rule defined; flagged as unresolved exception — risk of accidental distribution via standard email flow",
        "recommended_handling": "Halt standard process at D1; escalate to meeting owner or governance authority via A9 before any distribution occurs"
      },
      {
        "id": "E2",
        "description": "Unclear or unresolved action items from meeting",
        "trigger": "Notes are ambiguous or incomplete after the meeting",
        "current_handling": "Minute taker contacts relevant attendees for clarification before drafting summary",
        "recommended_handling": "Structured clarification step (A4) with a defined deadline to avoid summary delays"
      },
      {
        "id": "E3",
        "description": "Recipient list uncertainty",
        "trigger": "Meeting decisions affect stakeholders not present at the meeting",
        "current_handling": "Minute taker manually decides to expand distribution list based on judgment",
        "recommended_handling": "Define criteria or approval step for expanding recipients beyond attendee list"
      }
    ],
    "dependencies": [
      {"from": "A1", "to": "D1", "type": "control_flow"},
      {"from": "D1", "to": "A9", "type": "conditional_branch"},
      {"from": "D1", "to": "A3", "type": "conditional_branch"},
      {"from": "A3", "to": "D2", "type": "control_flow"},
      {"from": "D2", "to": "A4", "type": "conditional_branch"},
      {"from": "D2", "to": "A5", "type": "conditional_branch"},
      {"from": "A4", "to": "A5", "type": "control_flow"},
      {"from": "A3", "to": "A5", "type": "data_flow"},
      {"from": "A5", "to": "A6", "type": "control_flow"},
      {"from": "A6", "to": "A7", "type": "control_flow"},
      {"from": "A7", "to": "D3", "type": "control_flow"},
      {"from": "D3", "to": "A8", "type": "conditional_branch"}
    ]
  },
  "automation_opportunities": [
    {
      "target": "A3 - Extract Decisions and Action Items",
      "rationale": "If a transcript or structured meeting notes are available, an AI-based summarization model can extract decisions, action items, owners, and deadlines automatically, significantly reducing manual effort and extraction errors.",
      "required_data": ["Meeting transcript or structured notes", "Participant list with roles", "Meeting agenda"],
      "constraints": ["Transcript quality must be sufficient for reliable extraction", "Human review step should follow AI extraction to confirm accuracy", "Confidentiality check (D1) must precede any AI processing"],
      "confidence": "high"
    },
    {
      "target": "A5 - Draft Meeting Summary",
      "rationale": "Given a consistent expected structure (decisions, action items, owners, deadlines, attachments), a template-driven generation tool or AI drafting assistant can produce a near-complete summary with minimal manual input.",
      "required_data": ["Extracted decisions", "Confirmed action items with owners and deadlines", "Template structure", "Supporting material links or attachments"],
      "constraints": ["Template must be standardized and maintained", "Human approval of draft before sending is recommended", "Must not process confidential content without appropriate controls"],
      "confidence": "high"
    },
    {
      "target": "A6 - Determine Email Recipients",
      "rationale": "The attendee list is already available in the calendar system. A rule-based automation could pre-populate recipients from calendar data and flag when expansion beyond attendees may be needed, reducing manual curation effort.",
      "required_data": ["Calendar event attendee list", "Meeting metadata (topic, department, decision scope)"],
      "constraints": ["Rules for adding non-attendees require human judgment or governance policy definition", "Confidential meetings must be excluded from automated distribution"],
      "confidence": "medium"
    },
    {
      "target": "A7 - Send Meeting Summary Email",
      "rationale": "Once the summary is approved and recipients confirmed, the email sending step can be fully automated via an email client API triggered upon approval, including attaching or linking supporting materials.",
      "required_data": ["Approved summary document", "Finalized recipient list", "Supporting attachments or links"],
      "constraints": ["Requires prior human approval of both content and recipient list", "Confidentiality gate (D1) must have been cleared", "Scheduled send timing may need to be configurable"],
      "confidence": "high"
    },
    {
      "target": "A8 - Log Action Items in Task Tracker",
      "rationale": "Structured action items with owners and deadlines can be automatically pushed to the task tracker via integration, eliminating the need for manual re-entry and reducing the risk of items being missed.",
      "required_data": ["Action item descriptions", "Assigned owners", "Deadlines", "Task tracker API or integration credentials"],
      "constraints": ["Task tracker must support automated entry via API or integration", "Owner names must be resolvable to task tracker user accounts", "Duplicate detection logic needed if task tracker entries already exist"],
      "confidence": "high"
    },
    {
      "target": "D1 - Check for Confidential Content",
      "rationale": "Automated keyword scanning or classification models can flag potential confidential content in meeting notes before human review, providing an early warning layer rather than relying solely on manual detection.",
      "required_data": ["Meeting notes or transcript text", "Confidentiality keyword list or classification model"],
      "constraints": ["Automated flagging should supplement, not replace, human review", "False positive rate must be managed to avoid excessive escalations", "Classification rules must be defined and maintained by governance owners"],
      "confidence": "medium"
    }
  ],
  "remaining_gaps": [
    {
      "id": "G1",
      "description": "No formal policy exists for handling confidential meeting content",
      "impact": "Risk of sensitive information being distributed through the standard email flow without appropriate controls",
      "recommended_action": "Define and document a confidentiality handling policy, including who is authorized to receive sensitive summaries and what redaction or restricted-access mechanisms should be applied"
    },
    {
      "id": "G2",
      "description": "Volume and cycle time metrics are not tracked",
      "impact": "Impossible to objectively measure process efficiency, identify bottlenecks, or quantify the benefit of automation",
      "recommended_action": "Introduce lightweight logging of meeting count, summary creation time, and email send time to establish a baseline for process improvement measurement"
    },
    {
      "id": "G3",
      "description": "No defined criteria or approval mechanism for expanding recipients beyond meeting attendees",
      "impact": "Distribution decisions rely entirely on individual judgment, creating inconsistency and potential over- or under-distribution of information",
      "recommended_action": "Establish governance rules or a lightweight approval step for adding non-attendee recipients, especially for decisions with broader organizational impact"
    },
    {
      "id": "G4",
      "description": "No confirmation or acknowledgement step after the summary email is sent",
      "impact": "No visibility into whether recipients received, read, or acted on the summary or the action items assigned to them",
      "recommended_action": "Consider adding a read receipt mechanism or a follow-up step linked to action item deadlines in the task tracker"
    },
    {
      "id": "G5",
      "description": "Clarification process for ambiguous items (A4) is informal and time-bounded only by individual initiative",
      "impact": "Delays in summary distribution may occur if clarification is slow or not pursued consistently",
      "recommended_action": "Define a maximum clarification window and a fallback rule (e.g., flag item as pending in the summary rather than blocking distribution)"
    }
  ]
}
